button.style:
width: 20; height: 20;
                    base-background: group(rect(#FF17303F, 3 0 0 3, 1, #FF2E6E8E), icon(settings));
                    hover-background: group(rect(#FF1E4256, 3 0 0 3, 1, #FF57A8CC), icon(settings));
                    pressed-background: group(rect(#FF13252F, 3 0 0 3, 1, #FF2E6E8E), icon(settings));

element.style:
position: absolute; left: 100%; top: 0;
                            flex-direction: column; gap: 4; padding-all: 5;
                            background: rect(#F0102A38, 4, 1, #FF2E6E8E);

display: grid; gap: 3; padding-all: 3;
                                    grid-template-columns: 22 22 22; grid-template-rows: 22 22 22;
                                    background: rect(#FF16252F, 3, 1, #FF2E5A72);

button.style:
grid-column: 2; grid-row: 1;
                                base-background: rect(#FF24363F, 2, 1, #FF3D5A66);
                                hover-background: rect(#FF31505E, 2, 1, #FF6FA8BF);
                                pressed-background: rect(#FF1B2A31, 2, 1, #FF3D5A66);

